try {
  var t = localStorage.getItem('theme');
  if (!t && window.matchMedia) t = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  if (t) document.documentElement.setAttribute('data-theme', t);
  var d = document.documentElement;
  if (localStorage.getItem('fs-motion') === 'off') d.setAttribute('data-motion', 'off');
  if (localStorage.getItem('fs-fx') === 'off') d.setAttribute('data-fx', 'off');
  if (localStorage.getItem('fs-hotkeys') === 'off') d.setAttribute('data-keys', 'off');
  if (localStorage.getItem('fs-rail') === 'off') d.classList.add('rail-off');
  var _ffs = localStorage.getItem('fs-font') || localStorage.getItem('fs-help-font') || localStorage.getItem('fs-blog-font');
  if (_ffs) d.setAttribute('data-font', _ffs);
} catch (e) {}

(function () {
  'use strict';
  // ---- animated plan-comparison open/close ----
  (function () {
    var d = document.querySelector('.cmp-wrap');
    if (!d) return;
    var motionOff = function () { return document.documentElement.getAttribute('data-motion') === 'off'; };
    function setOpen(open) {
      if (open === d.hasAttribute('open')) return;
      if (motionOff()) { if (open) d.setAttribute('open', ''); else d.removeAttribute('open'); return; }
      if (open) {
        d.setAttribute('open', '');
        requestAnimationFrame(function () { d.classList.add('cmp-open'); });
      } else {
        d.classList.remove('cmp-open');
        var done = function () { d.removeEventListener('transitionend', onEnd); if (!d.classList.contains('cmp-open')) d.removeAttribute('open'); };
        var onEnd = function (e) { if (e.target === d.querySelector('.cmp-clip-in')) done(); };
        d.addEventListener('transitionend', onEnd);
        setTimeout(done, 500); /* safety */
      }
    }
    d.querySelector('summary').addEventListener('click', function (e) {
      e.preventDefault();
      setOpen(!d.hasAttribute('open'));
    });
  })();
  // ---- billing switcher + carousel ----
  var PLANS = ['free', 'monthly', 'monthly_3', 'monthly_6', 'yearly'];
  var cards = {};
  PLANS.forEach(function (id) {
    var el = document.querySelector('.plan-g[data-plan="' + id + '"]');
    if (el) cards[id] = el;
  });
  var stage = document.querySelector('.pricing-stage');
  var prevBtn = document.getElementById('carPrev');
  var nextBtn = document.getElementById('carNext');
  var billY = document.getElementById('billYearly');
  var billM = document.getElementById('billMonthly');

  var active = PLANS.indexOf('yearly'); // yearly view on load

  /* Yearly and 6 Months are the "hero" plans — slightly darker center card
     so their text is the most readable thing on the stage. */
  function markHeroes() {
    Object.keys(cards).forEach(function (id) {
      cards[id].classList.toggle('plan-hero', id === 'yearly' || id === 'monthly_6');
    });
  }
  markHeroes();

  /* finger swipe rotates the ring (phones keep the coverflow now) */
  (function () {
    if (!stage) return;
    var x0 = null, y0 = null, tracking = false;
    stage.addEventListener('touchstart', function (e) {
      if (e.touches.length !== 1) return;
      x0 = e.touches[0].clientX; y0 = e.touches[0].clientY; tracking = true;
    }, { passive: true });
    stage.addEventListener('touchmove', function (e) {
      if (!tracking) return;
      var dx = Math.abs(e.touches[0].clientX - x0);
      var dy = Math.abs(e.touches[0].clientY - y0);
      if (dx > 12 && dx > dy * 1.3) e.preventDefault(); // horizontal intent
    }, { passive: false });
    stage.addEventListener('touchend', function (e) {
      if (!tracking) return;
      tracking = false;
      var t = e.changedTouches[0];
      var dx = t.clientX - x0, dy = t.clientY - y0;
      if (Math.abs(dx) > 42 && Math.abs(dx) > Math.abs(dy) * 1.4) {
        step(dx < 0 ? 1 : -1);
      }
      x0 = y0 = null;
    }, { passive: true });
  })();

  /* place every card on the coverflow ring: slots -2..2 around the center */
  function layout() {
    var n = PLANS.length;
    PLANS.forEach(function (id, i) {
      var el = cards[id];
      if (!el) return;
      var off = i - active;
      if (off > n / 2) off -= n;
      if (off < -n / 2) off += n;
      el.setAttribute('data-pos', String(off));
      el.classList.toggle('active-plan', off === 0);
      /* Grid layout: every card is visible and reachable, so none of them
         may be hidden from assistive tech. */
      el.removeAttribute('aria-hidden');
    });
  }

  function setCenter(id) {
    var i = PLANS.indexOf(id);
    if (i >= 0) { active = i; layout(); }
  }

  function step(dir) {
    active = (active + dir + PLANS.length) % PLANS.length;
    layout();
  }

  if (prevBtn && nextBtn) {
    prevBtn.addEventListener('click', function () { step(-1); });
    nextBtn.addEventListener('click', function () { step(1); });
  }
  /* (Grid layout: no "click a background card to centre it" — every card's
     own CTA must stay a working link.) */
  document.addEventListener('keydown', function (e) {
    var sec = document.getElementById('pricing');
    if (!sec) return;
    if (window.FS_KEYS && !window.FS_KEYS.allow(e)) return;   /* Hotkeys switch + not while typing */
    var r = sec.getBoundingClientRect();
    if (r.top > window.innerHeight * 0.6 || r.bottom < window.innerHeight * 0.4) return;
    if (e.key === 'ArrowLeft') { step(-1); }
    else if (e.key === 'ArrowRight') { step(1); }
  });
  if (billY && billM) {
    billY.addEventListener('click', function () {
      billY.classList.add('active'); billY.setAttribute('aria-selected', 'true');
      billM.classList.remove('active'); billM.setAttribute('aria-selected', 'false');
      setCenter('yearly');
    });
    billM.addEventListener('click', function () {
      billM.classList.add('active'); billM.setAttribute('aria-selected', 'true');
      billY.classList.remove('active'); billY.setAttribute('aria-selected', 'false');
      setCenter('monthly_6');
    });
    /* monthly view: Free card first in the ring, then the rest
       (yearly view keeps the default order with Yearly centered) */
    var MONTHLY_ORDER = ['free', 'monthly_6', 'monthly', 'monthly_3', 'yearly'];
    var YEARLY_ORDER = PLANS.slice();
    function applyOrder() {
      var monthly = billM.classList.contains('active');
      var order = monthly ? MONTHLY_ORDER : YEARLY_ORDER;
      order.forEach(function (id) { if (cards[id]) stage.appendChild(cards[id]); });
    }
    applyOrder();
    billY.addEventListener('click', applyOrder);
    billM.addEventListener('click', applyOrder);
  }
  if (stage) layout();
  /* Self-heal: if the Animations toggle flips mid-session, re-apply the ring
     immediately so the coverflow is never left in a stale arrangement. */
  if (stage && 'MutationObserver' in window) {
    new MutationObserver(function () { layout(); }).observe(document.documentElement, { attributes: true, attributeFilter: ['data-motion'] });
  }
  window.addEventListener('load', function () { if (stage) layout(); });
})();

(function () {
  var root = document.documentElement;
  try {
    var stored = localStorage.getItem('theme') || localStorage.getItem('fs-theme') || '';
    if (stored === 'dark' || stored === 'light') root.setAttribute('data-theme', stored);
    else if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) root.setAttribute('data-theme', 'dark');
  } catch (e) {}

  // Reveal on scroll
  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting) { en.target.classList.add('in'); io.unobserve(en.target); }
      });
    }, { threshold: 0.12 });
    document.querySelectorAll('.reveal').forEach(function (el) { io.observe(el); });
  } else {
    document.querySelectorAll('.reveal').forEach(function (el) { el.classList.add('in'); });
  }
})();

// Theme: toggle + persist across pages (localStorage). No-flash read is inline in <head>.
(function () {
  function applyTheme(next) {
    document.documentElement.setAttribute('data-theme', next);
    try { localStorage.setItem('theme', next); } catch (e) {}
  }
  var btn = document.getElementById('themeToggle');
  if (btn) {
    btn.addEventListener('click', function () {
      var cur = document.documentElement.getAttribute('data-theme') || 'light';
      var next = cur === 'dark' ? 'light' : 'dark';
      applyTheme(next);
      btn.classList.add('spin');
      setTimeout(function () { btn.classList.remove('spin'); }, 400);
    });
  }
  // Keep theme in sync across open tabs/pages.
  window.addEventListener('storage', function (e) {
    if (e.key === 'theme' && e.newValue) {
      document.documentElement.setAttribute('data-theme', e.newValue);
    }
  });
})();

/* burger menu + navbar scroll elevation */
(function () {
  var burger = document.getElementById('navBurger');
  var sheet = document.getElementById('navMobile');
  if (burger && sheet) {
    var close = function () {
      sheet.classList.remove('open');
      burger.setAttribute('aria-expanded', 'false');
      setTimeout(function () { if (!sheet.classList.contains('open')) sheet.style.display = ''; }, 300);
    };
    burger.addEventListener('click', function (e) {
      e.stopPropagation();
      var open = sheet.classList.toggle('open');
      sheet.style.display = 'block';
      burger.setAttribute('aria-expanded', String(open));
      if (open) requestAnimationFrame(function () { sheet.classList.add('open'); });
      else close();
    });
    sheet.addEventListener('click', function (e) {
      if (e.target.closest('a')) close();
      e.stopPropagation();
    });
    document.addEventListener('click', function (e) {
      if (sheet.classList.contains('open') && !e.target.closest('#navMobile') && !e.target.closest('#navBurger')) close();
    });
    document.addEventListener('keydown', function (e) { if (e.key === 'Escape') close(); });
    window.addEventListener('resize', function () { if (window.innerWidth > 860) close(); });
  }
  var nav = document.querySelector('.home-nav');
  if (nav) {
    var upd = function () { nav.classList.toggle('scrolled', window.scrollY > 10); };
    upd();
    window.addEventListener('scroll', upd, { passive: true });
  }
})();

(function () {
  var root = document.documentElement;
  /* Staggered reveals: sibling cards rise in sequence */
  if ('IntersectionObserver' in window) {
    document.querySelectorAll('.reveal').forEach(function (el) {
      var parent = el.parentElement;
      if (!parent) return;
      var sibs = Array.prototype.filter.call(parent.children, function (c) {
        return c.classList && c.classList.contains('reveal');
      });
      var idx = sibs.indexOf(el);
      if (idx > 0) el.style.transitionDelay = Math.min(idx * 90, 420) + 'ms';
    });
  }

  /* iPhone-stage: pointer parallax with spring-back + idle float */
  (function () {
    var phone = document.getElementById('phone3d');
    if (!phone) return;
    var root = document.documentElement;
    var fine = window.matchMedia && matchMedia('(hover: hover) and (pointer: fine)').matches;
    var motionOff = root.getAttribute('data-motion') === 'off';
    if (!fine || motionOff) return;

    phone.classList.add('enter');
    setTimeout(function () { phone.classList.add('idle'); }, 1400);

    var stage = phone.parentElement;
    var raf = null, tx = 4, ty = -15, tz = 2, cx = 4, cy = -15, cz = 2;   // target/current deg
    function tick() {
      cx += (tx - cx) * .07;
      cy += (ty - cy) * .07;
      cz += (tz - cz) * .07;
      phone.style.setProperty('--prx', cx.toFixed(2) + 'deg');
      phone.style.setProperty('--pry', cy.toFixed(2) + 'deg');
      phone.style.setProperty('--prz', cz.toFixed(2) + 'deg');
      if (Math.abs(tx - cx) > .01 || Math.abs(ty - cy) > .01 || Math.abs(tz - cz) > .01) raf = requestAnimationFrame(tick);
      else raf = null;
    }
    stage.addEventListener('pointermove', function (e) {
      var r = stage.getBoundingClientRect();
      var px = (e.clientX - r.left) / r.width - .5;    // -0.5 .. 0.5
      var py = (e.clientY - r.top) / r.height - .5;
      tx = 4 - py * 7;           // lean toward/away with cursor height
      ty = -15 + px * 16;        // orbit around the standing pose
      tz = 7 + px * 5;           // slight roll, like a device on a stand
      phone.classList.remove('idle');
      if (!raf) raf = requestAnimationFrame(tick);
    });
    stage.addEventListener('pointerleave', function () {
      tx = 12; ty = -32; tz = 7; // spring back to the standing keynote pose
      if (!raf) raf = requestAnimationFrame(tick);
      setTimeout(function () { if (tx === 12 && ty === -32 && !raf) phone.classList.add('idle'); }, 1200);
    });
  })();

  /* The cursor-following 3D tilt that used to run here (a perspective()
     rotate + translateY(-4px) on every .feat/.step) is gone: cards
     that lurch under the pointer look like a demo, and the springy .55s
     transition made the lag obvious. Hover feedback is now depth only, and
     the cards still rise into view once on scroll via .reveal. */
})();

/* ==========================================================================
   Fast Scheduler — shared site footer.
   Injects the brand footer on every page (one source of truth). Replaces the
   legacy <footer class="site"> / <footer class="home-foot"> if present, and
   appends one before </body> otherwise. Assets are resolved relative to this
   script's own URL, so it works at any page depth. Follows the EN/RU language
   chosen in Settings (fs-lang) and re-renders when it changes.
   ========================================================================== */
(function () {
  'use strict';

  var script = document.currentScript;
  if (!script) {
    var tags = document.getElementsByTagName('script');
    for (var i = tags.length - 1; i >= 0; i--) {
      if (/site-footer\.js(\?|$)/.test(tags[i].src)) { script = tags[i]; break; }
    }
  }

  var BASE = '';
  try {
    if (script && script.src) BASE = script.src.replace(/scripts\/site-footer\.js.*$/, '');
  } catch (e) {}

  var STYLE_ID = 'fs-foot-css';
  var STYLE_HREF = BASE + 'styles/footer.css?v=20261019a5';

  var BOT_URL = 'https://t.me/FastSchedulerBot?start=start__website';
  var SUPPORT_URL = 'https://t.me/FastSchedulerSupport_bot';
  var EMAIL = 'mailto:fastschedulebot@gmail.com';

  var L = {
    en: {
      wordmark: 'Fast Scheduler',
      tagline: 'Schedule your Telegram channel posts once \u2014 they publish themselves, on time, in your timezone.',
      copy: '\u00a9 2026 Fast Scheduler \u00b7 Made for Telegram channels',
      cols: [
        { h: 'Product', links: [
          ['Features', 'index.html#features'],
          ['How it works', 'index.html#how'],
          ['Pricing', 'index.html#pricing'],
          ['Scheduling', 'help/c/scheduling/'],
          ['Batch scheduling', 'help/a/qa_schedule_many_at_once/'],
          ['Sender Bots', 'help/c/bots/'],
          ['Media Storage', 'help/c/media_storage/']
        ] },
        { h: 'Resources', links: [
          ['Help Center', 'help/'],
          ['Getting Started', 'help/c/start/'],
          ['Blog', 'blog/index.html'],
          ['Premium', 'help/c/premium/'],
          ['Referrals', 'help/c/referral/'],
          ['FAQ', 'index.html#faq']
        ] },
        { h: 'Support', links: [
          ['Open Bot', BOT_URL, 1],
          ['Support chat', SUPPORT_URL, 1],
          ['Feedback', 'help/c/feedback/'],
          ['Contact', 'help/c/contact/'],
          ['Email us', EMAIL, 1]
        ] },
        { h: 'Legal', links: [
          ['Privacy', 'legal/privacy/'],
          ['Terms', 'legal/terms/'],
          ['Refunds', 'legal/refund-policy/'],
          ['Data Deletion', 'help/a/privacy_delete/']
        ] }
      ]
    },
    ru: {
      wordmark: 'Fast Scheduler',
      tagline: '\u041f\u043b\u0430\u043d\u0438\u0440\u0443\u0439\u0442\u0435 \u043f\u043e\u0441\u0442\u044b \u0432 Telegram-\u043a\u0430\u043d\u0430\u043b\u0435 \u043e\u0434\u0438\u043d \u0440\u0430\u0437 \u2014 \u0434\u0430\u043b\u044c\u0448\u0435 \u043e\u043d\u0438 \u043f\u0443\u0431\u043b\u0438\u043a\u0443\u044e\u0442\u0441\u044f \u0441\u0430\u043c\u0438, \u0432\u043e\u0432\u0440\u0435\u043c\u044f \u0438 \u0432 \u0432\u0430\u0448\u0435\u043c \u0447\u0430\u0441\u043e\u0432\u043e\u043c \u043f\u043e\u044f\u0441\u0435.',
      copy: '\u00a9 2026 Fast Scheduler \u00b7 \u0421\u0434\u0435\u043b\u0430\u043d\u043e \u0434\u043b\u044f Telegram-\u043a\u0430\u043d\u0430\u043b\u043e\u0432',
      cols: [
        { h: '\u041f\u0440\u043e\u0434\u0443\u043a\u0442', links: [
          ['\u0412\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u0438', 'index.html#features'],
          ['\u041a\u0430\u043a \u044d\u0442\u043e \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442', 'index.html#how'],
          ['\u0422\u0430\u0440\u0438\u0444\u044b', 'index.html#pricing'],
          ['\u041f\u043b\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435', 'help/c/scheduling/'],
          ['\u041f\u0430\u043a\u0435\u0442\u043d\u043e\u0435 \u043f\u043b\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435', 'help/a/qa_schedule_many_at_once/'],
          ['\u0411\u043e\u0442\u044b-\u043e\u0442\u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u0438', 'help/c/bots/'],
          ['\u041c\u0435\u0434\u0438\u0430\u0442\u0435\u043a\u0430', 'help/c/media_storage/']
        ] },
        { h: '\u0420\u0435\u0441\u0443\u0440\u0441\u044b', links: [
          ['\u0426\u0435\u043d\u0442\u0440 \u043f\u043e\u043c\u043e\u0449\u0438', 'help/'],
          ['\u041d\u0430\u0447\u0430\u043b\u043e \u0440\u0430\u0431\u043e\u0442\u044b', 'help/c/start/'],
          ['\u0411\u043b\u043e\u0433', 'blog/index.html'],
          ['\u041f\u0440\u0435\u043c\u0438\u0443\u043c', 'help/c/premium/'],
          ['\u0420\u0435\u0444\u0435\u0440\u0430\u043b\u044b', 'help/c/referral/'],
          ['\u0412\u043e\u043f\u0440\u043e\u0441\u044b \u0438 \u043e\u0442\u0432\u0435\u0442\u044b', 'index.html#faq']
        ] },
        { h: '\u041f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430', links: [
          ['\u041e\u0442\u043a\u0440\u044b\u0442\u044c \u0431\u043e\u0442\u0430', BOT_URL, 1],
          ['\u0427\u0430\u0442 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438', SUPPORT_URL, 1],
          ['\u041e\u0431\u0440\u0430\u0442\u043d\u0430\u044f \u0441\u0432\u044f\u0437\u044c', 'help/c/feedback/'],
          ['\u041a\u043e\u043d\u0442\u0430\u043a\u0442\u044b', 'help/c/contact/'],
          ['\u041d\u0430\u043f\u0438\u0441\u0430\u0442\u044c \u043d\u0430\u043c', EMAIL, 1]
        ] },
        { h: '\u041f\u0440\u0430\u0432\u043e\u0432\u0430\u044f \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044f', links: [
          ['\u041a\u043e\u043d\u0444\u0438\u0434\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c', 'legal/privacy/'],
          ['\u0423\u0441\u043b\u043e\u0432\u0438\u044f', 'legal/terms/'],
          ['\u0412\u043e\u0437\u0432\u0440\u0430\u0442\u044b', 'legal/refund-policy/'],
          ['\u0423\u0434\u0430\u043b\u0435\u043d\u0438\u0435 \u0434\u0430\u043d\u043d\u044b\u0445', 'help/a/privacy_delete/']
        ] }
      ]
    }
  };

  function esc(s) {
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function currentLang() {
    try {
      var saved = localStorage.getItem('fs-lang');
      if (saved === 'ru' || saved === 'en') return saved;
    } catch (e) {}
    return (document.documentElement.getAttribute('lang') === 'ru') ? 'ru' : 'en';
  }

  function hrefFor(href) {
    return /^(https?:|mailto:|tel:|\/)/.test(href) ? href : BASE + href;
  }

  function li(item) {
    var at = item[2] ? ' target="_blank" rel="noopener noreferrer"' : '';
    return '<li><a href="' + esc(hrefFor(item[1])) + '"' + at + '>' + esc(item[0]) + '</a></li>';
  }

  function column(c) {
    return '<div class="fs-foot-col"><h3>' + esc(c.h) + '</h3><ul>' +
      c.links.map(li).join('') + '</ul></div>';
  }

  function html(t) {
    var words = String(t.wordmark).split(' ');
    var line1 = words[0];
    var line2 = words.slice(1).join(' ') || line1;
    var stack = '<tspan x="720" y="140">' + esc(line1) + '</tspan>' +
      '<tspan x="720" y="312">' + esc(line2) + '</tspan>';
    return '<footer class="fs-foot" role="contentinfo">' +
      '<div class="wrap fs-foot-main">' +
        '<div class="fs-foot-brand">' +
          '<a class="fs-foot-logo" href="' + esc(BASE + 'index.html') + '" aria-label="' + esc(t.wordmark) + '">' +
            '<img src="' + esc(BASE + 'brand-logo.png') + '" alt="' + esc(t.wordmark) + '" width="56" height="56" loading="lazy" decoding="async">' +
          '</a>' +
          '<p class="fs-foot-tag">' + esc(t.tagline) + '</p>' +
        '</div>' +
        '<div class="fs-foot-cols">' + t.cols.map(column).join('') + '</div>' +
      '</div>' +
      '<div class="fs-foot-mark" aria-hidden="true">' +
        '<svg class="fs-foot-word" viewBox="0 0 1440 172" preserveAspectRatio="xMidYMid meet" focusable="false" aria-hidden="true">' +
          '<defs>' +
            '<linearGradient id="fsWordGrad" x1="0" y1="0" x2="1" y2="1">' +
              '<stop offset="0" stop-color="#eafff6" stop-opacity="0.07"/>' +
              '<stop offset="0.42" stop-color="#ffffff" stop-opacity="0.18"/>' +
              '<stop offset="0.58" stop-color="#8ff2c6" stop-opacity="0.28"/>' +
              '<stop offset="1" stop-color="#eafff6" stop-opacity="0.07"/>' +
              '<animateTransform attributeName="gradientTransform" type="rotate" from="0 0.5 0.5" to="360 0.5 0.5" dur="30s" repeatCount="indefinite"/>' +
            '</linearGradient>' +
            '<filter id="fsWordBlur" x="-10%" y="-40%" width="120%" height="180%">' +
              '<feGaussianBlur stdDeviation="5"/>' +
            '</filter>' +
          '</defs>' +
          '<g class="fs-word-wide">' +
            '<text class="fs-foot-word-text" x="720" y="140" text-anchor="middle" fill="#7ef0bf" fill-opacity="0.16" filter="url(#fsWordBlur)">' + esc(t.wordmark) + '</text>' +
            '<text class="fs-foot-word-text" x="720" y="140" text-anchor="middle" fill="url(#fsWordGrad)" stroke="rgba(255,255,255,0.05)" stroke-width="1">' + esc(t.wordmark) + '</text>' +
          '</g>' +
          '<g class="fs-word-stack">' +
            '<text class="fs-foot-word-text" text-anchor="middle" fill="#7ef0bf" fill-opacity="0.16" filter="url(#fsWordBlur)">' + stack + '</text>' +
            '<text class="fs-foot-word-text" text-anchor="middle" fill="url(#fsWordGrad)" stroke="rgba(255,255,255,0.05)" stroke-width="1">' + stack + '</text>' +
          '</g>' +
        '</svg>' +
      '</div>' +
      '<div class="wrap fs-foot-base"><span>' + esc(t.copy) + '</span></div>' +
    '</footer>';
  }

  function ensureCSS() {
    if (document.getElementById(STYLE_ID)) return;
    var link = document.createElement('link');
    link.id = STYLE_ID;
    link.rel = 'stylesheet';
    link.href = STYLE_HREF;
    (document.head || document.documentElement).appendChild(link);
  }

  // Scale the wordmark so it always spans the footer width exactly, regardless
  // of which font actually renders, then grow the SVG viewBox vertically to
  // contain the glyphs. Scaling by width alone used to push the tops of the
  // letters above y=0, where the SVG clipped them.
  var WORD_W = 1440;
  var WORD_H = 172;
  var WORD_BASE_Y = 140;
  var WORD_PAD_X = 14;
  var WORD_PAD_Y = 10;

  function narrowWord() {
    try {
      if (window.matchMedia) return window.matchMedia('(max-width: 540px)').matches;
    } catch (e) {}
    return (window.innerWidth || 0) <= 540;
  }

  function setWordLines(text, gap, shift) {
    var lines = text.querySelectorAll('tspan');
    var i;
    if (!lines.length) {
      text.setAttribute('y', (WORD_BASE_Y + shift).toFixed(2));
      return;
    }
    for (i = 0; i < lines.length; i++) {
      lines[i].setAttribute('x', WORD_W / 2);
      lines[i].setAttribute('y', (WORD_BASE_Y + shift + i * gap).toFixed(2));
    }
  }

  function fitWord(root) {
    var svg = root.querySelector('.fs-foot-word');
    if (!svg || !svg.setAttribute) return;
    var wide = root.querySelector('.fs-word-wide');
    var stack = root.querySelector('.fs-word-stack');
    var narrow = narrowWord();
    if (wide) wide.style.display = narrow ? 'none' : 'inline';
    if (stack) stack.style.display = narrow ? 'inline' : 'none';
    var group = narrow ? stack : wide;
    if (!group) return;
    var texts = group.querySelectorAll('.fs-foot-word-text');
    if (!texts.length) return;

    svg.setAttribute('viewBox', '0 0 ' + WORD_W + ' ' + WORD_H);
    var i;
    var gap = WORD_H * 0.98;
    for (i = 0; i < texts.length; i++) {
      texts[i].style.fontSize = WORD_H + 'px';
      setWordLines(texts[i], gap, 0);
    }

    var probe = texts[0].getBBox ? texts[0].getBBox() : null;
    if (!probe || !probe.width) return;

    var target = WORD_W - WORD_PAD_X * 2;
    var size = WORD_H * target / probe.width;
    gap = size * 0.98;
    for (i = 0; i < texts.length; i++) {
      texts[i].style.fontSize = size.toFixed(2) + 'px';
      setWordLines(texts[i], gap, 0);
    }

    var box = texts[0].getBBox ? texts[0].getBBox() : probe;
    var height = Math.max(WORD_H, Math.ceil(box.height + WORD_PAD_Y * 2));
    var shift = WORD_PAD_Y - box.y;
    for (i = 0; i < texts.length; i++) setWordLines(texts[i], gap, shift);
    svg.setAttribute('viewBox', '0 0 ' + WORD_W + ' ' + height);
  }

  function whenFontsReady(fn) {
    try {
      if (document.fonts && document.fonts.ready) {
        document.fonts.load('700 100px "Space Grotesk"').catch(function () {});
        document.fonts.ready.then(fn).catch(fn);
        return;
      }
    } catch (e) {}
    fn();
  }

  function render() {
    var t = L[currentLang()] || L.en;
    ensureCSS();
    var node = new DOMParser().parseFromString(html(t), 'text/html').body.firstChild;
    var old = document.querySelector('footer.fs-foot, footer.site, footer.home-foot');
    if (old && old.parentNode) {
      // The legacy footer usually lives inside .wrap, which made the green
      // background stop at the content column and look cut off on both sides.
      // Move the new footer beside the outermost wrapper so it spans the page.
      var top = old;
      while (top.parentNode && top.parentNode !== document.body) top = top.parentNode;
      if (top.parentNode === document.body) {
        top.parentNode.insertBefore(node, top.nextSibling);
      } else if (document.body) {
        document.body.appendChild(node);
      }
      if (old.parentNode) old.parentNode.removeChild(old);
    } else if (document.body) document.body.appendChild(node);
    fitWord(node);
    whenFontsReady(function () { fitWord(node); });
  }

  render();

  var wordResizeTimer;
  window.addEventListener('resize', function () {
    clearTimeout(wordResizeTimer);
    wordResizeTimer = setTimeout(function () {
      var foot = document.querySelector('footer.fs-foot');
      if (foot) fitWord(foot);
    }, 140);
  });

  window.addEventListener('fs-lang-change', render);
  window.addEventListener('fs-lang-applied', render);
})();

/* Hide-on-scroll chrome (shared, every page, mobile + desktop).
   - html.nav-hidden slides the navbar off-screen with a transform (GPU,
     animated — never display:none, so the layout never jumps or reflows).
   - Elements that sit below the navbar and hug the same edge (bottom bars:
     toc-bar, cookie banner, Contents FAB, jump FAB) get .nav-slide-up /
     .nav-slide-down so they slide away/together with the bar instead of
     leaving an empty strip where the navbar used to be.
   - Desktop and mobile behave the same; "down" hides, scrolling up reveals.
   - Never hides while a popover/sheet/menu is open, while typing, or within
     350ms of a programmatic jump (anchor links, scroll-jump FAB).
*/
(function () {
  var doc = document.documentElement;
  var body = document.body;
  if (!body) return;

  var bar = document.querySelector('.home-nav') || document.querySelector('header.site');
  if (!bar) return;

  var HIDE_AFTER = 140;   /* px of downward travel before hiding */
  var SHOW_DELTA = 6;     /* px of upward travel before showing */
  var SNAP_AT_TOP = 40;   /* always show near the top of the page */
  var PIN = 350;          /* grace period after programmatic scrolls */

  var lastY = currentY(), pinned = 0, hidden = false, ticking = false;

  /* Publish the bar's height so CSS can release its reserved space when it
     hides (fixed bars on the homepage use padding-top; the legal app-shell
     is a flex column where the header owns a layout slot). */
  function measure() {
    doc.style.setProperty('--nav-h', bar.offsetHeight + 'px');
  }
  measure();
  window.addEventListener('resize', measure, { passive: true });

  function inner() {
    /* legal pages on phones scroll inside main.legal (app shell) */
    if (body.classList.contains('legal') && window.matchMedia &&
        matchMedia('(max-width: 760px)').matches) {
      var m = document.querySelector('main.legal');
      if (m) return m;
    }
    return null;
  }
  function currentY() {
    var sc = inner();
    return sc ? sc.scrollTop : (window.scrollY || window.pageYOffset || 0);
  }
  function maxY() {
    var sc = inner();
    if (sc) return sc.scrollHeight - sc.clientHeight;
    return document.documentElement.scrollHeight - window.innerHeight;
  }

  function openPopoverOpen() {
    /* don't fight an open menu/sheet — it may be anchored to the bar */
    if (document.querySelector('.glass-pop.open, .nav-mobile.open, .toc-sheet.open, .site-menu-pop.open, .hc-toc-sheet.open, .blog-toc-sheet.open')) return true;
    var el = document.activeElement;
    if (el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.isContentEditable)) return true;
    return false;
  }

  function show() {
    if (!hidden) return;
    hidden = false;
    doc.classList.remove('nav-hidden');
  }
  function hide() {
    if (hidden) return;
    hidden = true;
    doc.classList.add('nav-hidden');
  }

  function update() {
    ticking = false;
    var y = currentY();
    var delta = y - lastY;

    if (Date.now() < pinned || openPopoverOpen()) { lastY = y; show(); return; }
    if (y <= SNAP_AT_TOP) { lastY = y; show(); return; }

    if (delta > 0 && y > HIDE_AFTER) {
      if (delta > SHOW_DELTA || !hidden) hide();
    } else if (delta < -SHOW_DELTA) {
      show();
    }
    lastY = y;
  }

  function onScroll() {
    if (!ticking) { ticking = true; requestAnimationFrame(update); }
  }

  window.addEventListener('scroll', onScroll, { passive: true });
  var sc = inner();
  if (sc) sc.addEventListener('scroll', onScroll, { passive: true });
  window.addEventListener('resize', function () {
    /* scroller may change between mobile/desktop layouts */
    measure();
    var n = inner();
    if (n !== sc) { if (sc) sc.removeEventListener('scroll', onScroll); sc = n; if (sc) sc.addEventListener('scroll', onScroll, { passive: true }); }
    lastY = currentY(); show();
  }, { passive: true });

  /* anchor links and the jump FAB scroll programmatically — never fight them */
  document.addEventListener('click', function (e) {
    if (e.target.closest && e.target.closest('a[href^="#"], .jump-fab, .hc-fab, .toc-burger')) pinned = Date.now() + PIN;
  });
  window.addEventListener('fs-jump', function () { pinned = Date.now() + PIN; });

  /* keyboard scroll keys: reveal immediately so focus is never lost */
  window.addEventListener('keydown', function (e) {
    var k = e.key;
    if (k === 'ArrowUp' || k === 'PageUp' || k === 'Home' || k === 'End' || k === 'ArrowDown' || k === 'PageDown') show();
  });

  /* touch: a touchend followed by upward momentum is handled by scroll events;
     a simple tap on the page near the top restores the bar */
  body.addEventListener('touchstart', function () { pinned = Date.now() + 120; }, { passive: true });

  lastY = currentY();
})();

// Site settings: theme, motion, effects. One controller for every page —
// state lives in localStorage, so a change here applies site-wide.
// (No-flash reads happen inline in each page's <head>.)
(function () {
  var root = document.documentElement;
  var btn = document.getElementById('settingsBtn');
  var menu = document.getElementById('settingsMenu');
  var wrap = btn ? btn.parentElement : null;
  var closeT = null, hoverT = null;

  /* The menu drops below the gear by default. From the side rail (or any
     short viewport) there may be no room below, which used to park the
     bottom rows off-screen with no way to reach them — flip it above the
     gear instead and let it scroll internally as a last resort. */
  function placeMenu() {
    if (!menu || !wrap || !btn) return;
    menu.classList.remove('menu-up');
    menu.style.maxHeight = '';
    var r = menu.getBoundingClientRect();
    var gearTop = btn.getBoundingClientRect().top;
    var below = window.innerHeight - 8 - r.top;   /* room under the gear */
    var above = gearTop - 12 - 8;                 /* room over the gear  */
    if (r.height > below && above > below) {
      menu.classList.add('menu-up');
      if (r.height > above) menu.style.maxHeight = Math.max(120, above) + 'px';
    } else if (r.height > below) {
      menu.style.maxHeight = Math.max(120, below) + 'px';
    }
  }
  function openMenu() {
    if (menu && !menu.classList.contains('open')) {
      clearTimeout(closeT);
      menu.classList.add('open');
      if (btn) btn.setAttribute('aria-expanded', 'true');
      placeMenu();
    }
  }
  function closeMenu() {
    if (menu && menu.classList.contains('open')) {
      menu.classList.remove('open');
      if (btn) btn.setAttribute('aria-expanded', 'false');
    }
  }

  if (btn && menu && wrap) {
    if (window.matchMedia && matchMedia('(hover: hover) and (pointer: fine)').matches) {
      wrap.addEventListener('mouseenter', function () { clearTimeout(closeT); hoverT = setTimeout(openMenu, 70); });
      wrap.addEventListener('mouseleave', function () { clearTimeout(hoverT); closeT = setTimeout(closeMenu, 160); });
    }
    btn.addEventListener('click', function (e) {
      e.stopPropagation(); clearTimeout(hoverT);
      menu.classList.contains('open') ? closeMenu() : openMenu();
    });
    menu.addEventListener('click', function (e) { if (e.target.closest('a')) closeMenu(); });
    document.addEventListener('click', function (e) { if (!wrap.contains(e.target)) closeMenu(); });
    document.addEventListener('keydown', function (e) { if (e.key === 'Escape') { closeSiteMenu(); closeMenu(); } });
  }

  /* ---------- Help quick-search popover (hangs off the navbar Help pill) ---------- */
  var siteWrap = document.querySelector('.site-menu-wrap');
  var sitePop = document.getElementById('siteMenu');
  function openSiteMenu() {
    if (sitePop && !sitePop.classList.contains('open')) {
      sitePop.classList.add('open');
      var row = siteWrap && siteWrap.querySelector('.site-menu-row');
      if (row) row.setAttribute('aria-expanded', 'true');
    }
  }
  function closeSiteMenu() {
    if (sitePop && sitePop.classList.contains('open')) {
      sitePop.classList.remove('open');
      var row = siteWrap && siteWrap.querySelector('.site-menu-row');
      if (row) row.setAttribute('aria-expanded', 'false');
    }
  }
  if (siteWrap && sitePop) {
    var sCloseT = null, sHoverT = null;
    var finePointer = window.matchMedia && matchMedia('(hover: hover) and (pointer: fine)').matches;

    /* Hovering the Help Center pill opens the quick-search popover (desktop
       fine pointers only). The pill itself stays a plain navigation link. */
    var rowIsHelp = /help\.html|help\//.test(
      (siteWrap.querySelector('.site-menu-row') || {}).getAttribute &&
      siteWrap.querySelector('.site-menu-row').getAttribute('href') || '');
    function keepOpen() { clearTimeout(sCloseT); }
    if (finePointer && rowIsHelp) {
      siteWrap.addEventListener('mouseenter', function () { clearTimeout(sCloseT); sHoverT = setTimeout(openSiteMenu, 60); });
      siteWrap.addEventListener('mouseleave', function () { clearTimeout(sHoverT); sCloseT = setTimeout(closeSiteMenu, 450); });
    }
    sitePop.addEventListener('mouseenter', keepOpen);
    sitePop.addEventListener('pointerdown', keepOpen);
    sitePop.addEventListener('focusin', keepOpen);

    /* The row is a genuine link that should just NAVIGATE — on every page,
       desktop and mobile. It used to intercept plain left clicks on desktop
       and open the quick-search popover instead, which read as "Main site
       opens the help search". The search stays reachable through the chevron
       row and "Open Help Center" inside the popover; direct navigation wins
       here (cmd/ctrl/middle-click still work natively). */
    var siteRow = siteWrap.querySelector('.site-menu-row');
    if (siteRow) {
      /* phones: no hover, popover is cramped and it looks broken */
      var coarse = window.matchMedia && matchMedia('(hover: none), (pointer: coarse)').matches;
      if (coarse) {
        siteRow.addEventListener('click', function () { closeMenu(); closeSiteMenu(); });
      }
    }
    sitePop.addEventListener('click', function (e) {
      if (e.target.closest('a')) { keepOpen(); closeSiteMenu(); }
    });
    document.addEventListener('click', function (e) {
      if (!siteWrap.contains(e.target)) closeSiteMenu();
    });
    /* the chevron on the Help row toggles the quick-search popover without
       navigating (the row itself is a plain navigation link now). On the help
       center page the row is "Main site" — it has no chevron anyway. */
    var chev = siteWrap.querySelector('.site-menu-row .chev');
    if (chev) {
      chev.style.pointerEvents = 'auto';
      chev.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        if (sitePop.classList.contains('open')) closeSiteMenu(); else openSiteMenu();
      });
    }
  }

  /* ---------- Dark mode ---------- */
  var rowDark = document.getElementById('rowDark');
  function syncDark() {
    if (rowDark) rowDark.setAttribute('aria-pressed', root.getAttribute('data-theme') === 'dark' ? 'true' : 'false');
  }
  if (rowDark) {
    rowDark.addEventListener('click', function (e) { e.stopPropagation();
      var next = root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
      root.setAttribute('data-theme', next);
      try { localStorage.setItem('theme', next); } catch (err) {}
      syncDark();
    });
  }

  /* ---------- Animations (motion) ---------- */
  var rowAnim = document.getElementById('rowAnim');
  function syncAnim() {
    if (rowAnim) rowAnim.setAttribute('aria-pressed', root.getAttribute('data-motion') === 'off' ? 'false' : 'true');
  }
  if (rowAnim) {
    rowAnim.addEventListener('click', function (e) { e.stopPropagation();
      var off = root.getAttribute('data-motion') === 'off';
      if (off) { root.removeAttribute('data-motion'); try { localStorage.setItem('fs-motion', 'on'); } catch (err) {} }
      else { root.setAttribute('data-motion', 'off'); try { localStorage.setItem('fs-motion', 'off'); } catch (err) {} }
      syncAnim();
    });
  }

  /* ---------- Effects (shine, hover lifts, breathing, glow) ---------- */
  var rowFx = document.getElementById('rowFx');
  function syncFx() {
    if (rowFx) rowFx.setAttribute('aria-pressed', root.getAttribute('data-fx') === 'off' ? 'false' : 'true');
  }
  if (rowFx) {
    rowFx.addEventListener('click', function (e) { e.stopPropagation();
      var off = root.getAttribute('data-fx') === 'off';
      if (off) { root.removeAttribute('data-fx'); try { localStorage.setItem('fs-fx', 'on'); } catch (err) {} }
      else { root.setAttribute('data-fx', 'off'); try { localStorage.setItem('fs-fx', 'off'); } catch (err) {} }
      syncFx();
    });
  }

  /* ---------- Hotkeys ----------
     One switch for every keyboard shortcut on the site (the rail's "s", the
     jump button's "g"/Home/End, the pricing ring's arrow keys). Other scripts
     read FS_KEYS.enabled() and listen for the change event, so toggling it takes
     effect immediately without a reload. K itself always stays live as the
     escape hatch (see hotkeys.js): an accidental press can never strand the
     visitor with no keyboard way back on. */
  var rowKeys = document.getElementById('rowKeys');
  var FS_KEYS = {
    enabled: function () { return root.getAttribute('data-keys') !== 'off'; },
    /* every shortcut must also stay out of the way while typing */
    typing: function (el) {
      el = el || document.activeElement;
      if (!el) return false;
      var tag = (el.tagName || '').toUpperCase();
      return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || el.isContentEditable === true;
    },
    /* true when a shortcut may run: enabled, not typing, no modifier held */
    allow: function (e) {
      if (!FS_KEYS.enabled()) return false;
      if (e && (e.metaKey || e.ctrlKey || e.altKey)) return false;
      return !FS_KEYS.typing();
    }
  };
  window.FS_KEYS = FS_KEYS;

  function syncKeys() {
    var on = FS_KEYS.enabled();
    if (rowKeys) rowKeys.setAttribute('aria-pressed', on ? 'true' : 'false');
  }
  if (rowKeys) {
    rowKeys.addEventListener('click', function (e) {
      e.stopPropagation();
      var on = !FS_KEYS.enabled();
      if (on) root.removeAttribute('data-keys'); else root.setAttribute('data-keys', 'off');
      try { localStorage.setItem('fs-hotkeys', on ? 'on' : 'off'); } catch (err) {}
      syncKeys();
      try { window.dispatchEvent(new CustomEvent('fs-hotkeys-change', { detail: { on: on } })); } catch (err) {}
    });
  }

  /* ---------- Font size (global, site-wide) ----------
     One S/M/L control in every settings menu. State lives in `fs-font`
     (migrated once from the old per-section fs-help-font / fs-blog-font
     keys); the size applies through `html[data-font]` + root font-size
     rules in main.css, so it works on every page. Per-section painters
     (help/blog inlines) mirror the legacy attrs and listen for the
     fs-font-change event to repaint their own toggles. */
  function readFont() {
    try {
      var v = localStorage.getItem('fs-font');
      if (v === 's' || v === 'm' || v === 'l') return v;
      v = localStorage.getItem('fs-help-font') || localStorage.getItem('fs-blog-font');
      if (v === 's' || v === 'm' || v === 'l') {
        try { localStorage.setItem('fs-font', v); } catch (err2) {}
        return v;
      }
    } catch (err) {}
    return 'm';
  }
  function applyFont(v) {
    if (v === 's' || v === 'l') {
      root.setAttribute('data-font', v);
      root.setAttribute('data-hcfont', v);
      root.setAttribute('data-blogfont', v);
    } else {
      root.removeAttribute('data-font');
      root.removeAttribute('data-hcfont');
      root.removeAttribute('data-blogfont');
    }
    Array.prototype.forEach.call(
      document.querySelectorAll('[data-fonts] button, [data-blog-fonts] button, [data-global-fonts] button'),
      function (b) { b.classList.toggle('on', (v || 'm') === b.getAttribute('data-font')); });
  }
  function setFont(v) {
    if (v !== 's' && v !== 'l') v = 'm';
    try {
      localStorage.setItem('fs-font', v);
      localStorage.setItem('fs-help-font', v);
      localStorage.setItem('fs-blog-font', v);
    } catch (err) {}
    applyFont(v);
    try { window.dispatchEvent(new CustomEvent('fs-font-change', { detail: { font: v } })); } catch (err) {}
  }
  window.FS_FONT = { get: readFont, set: setFont, apply: applyFont };
  document.addEventListener('click', function (e) {
    if (!e.target.closest) return;
    var f = e.target.closest('[data-fonts] button, [data-blog-fonts] button, [data-global-fonts] button');
    if (f) { e.stopPropagation(); setFont(f.getAttribute('data-font')); }
  });

