      gatherReacts(msg, [
        { at: 4600, n: 24 },   /* 👍 */
        { at: 6200, n: 11 },   /* 🔥 */
        { at: 7900, n: 4 }     /* ⭐ paid */
      ]);

      /* post 2 — its own real send time */
      later(function () {
        tickTo(SCHEDULED_POSTS[1].time);
