      later(function () {
        countUp(m2.querySelector('.cp-views b'), 148);
      }, 6300);
      gatherReacts(m2, [
        { at: 6500, n: 17 },
        { at: 7600, n: 6 },
        { at: 8600, n: 2 }
      ]);

